-- 근태 정정 패치 사후 점검. 조회만 수행하며 COMMIT하지 않는다.
SET DEFINE OFF
SELECT '1 correction table' ITEM,CASE WHEN COUNT(*)=1 THEN 'PASS' ELSE 'FAIL' END RESULT FROM USER_TABLES WHERE TABLE_NAME='ATTENDANCE_CORRECTION'
UNION ALL SELECT '2 columns:16',CASE WHEN COUNT(*)=16 THEN 'PASS' ELSE 'FAIL' END FROM USER_TAB_COLUMNS WHERE TABLE_NAME='ATTENDANCE_CORRECTION'
UNION ALL SELECT '3 enabled validated constraints:15',CASE WHEN COUNT(*)=15 THEN 'PASS' ELSE 'FAIL' END FROM USER_CONSTRAINTS WHERE TABLE_NAME='ATTENDANCE_CORRECTION' AND CONSTRAINT_NAME IN ('PK_ATTENDANCE_CORRECTION','UQ_82_01','CK_82_01','CK_82_02','CK_82_03','CK_82_04','CK_82_05','CK_82_06','CK_82_07','CK_82_08','FK_82_01','FK_82_02','FK_82_03','FK_82_04','FK_82_05') AND STATUS='ENABLED' AND VALIDATED='VALIDATED'
UNION ALL SELECT '4 original check-in constraint',CASE WHEN COUNT(*)=1 THEN 'PASS' ELSE 'FAIL' END FROM USER_CONSTRAINTS WHERE TABLE_NAME='ATTENDANCE_CORRECTION' AND CONSTRAINT_NAME='CK_82_08' AND STATUS='ENABLED' AND VALIDATED='VALIDATED'
UNION ALL SELECT '5 query indexes:3',CASE WHEN COUNT(*)=3 THEN 'PASS' ELSE 'FAIL' END FROM USER_INDEXES WHERE TABLE_NAME='ATTENDANCE_CORRECTION' AND INDEX_NAME IN ('UX_82_01','IX_82_01','IX_82_02') AND STATUS='VALID'
UNION ALL SELECT '6 enabled status codes:5',CASE WHEN COUNT(*)=5 AND SUM(CASE WHEN USE_YN='Y' THEN 1 ELSE 0 END)=5 THEN 'PASS' ELSE 'FAIL' END FROM COMMON_CODE WHERE CODE IN ('CORRECTION_STATUS','ACR_REQUESTED','ACR_APPROVED','ACR_REJECTED','ACR_CANCELED')
UNION ALL SELECT '7 sequence maxima:66',CASE WHEN COUNT(*)=66 AND SUM(CASE WHEN MAX_VALUE=99999 THEN 1 ELSE 0 END)=66 THEN 'PASS' ELSE 'FAIL' END FROM USER_SEQUENCES WHERE SEQUENCE_NAME IN ('SQ_COMPANY','SQ_DEPARTMENT','SQ_JOB_GRADE','SQ_BRANCH','SQ_EMPLOYEE','SQ_USER_ACCOUNT','SQ_ACCOUNT_REQUEST','SQ_EMAIL_VERIFICATION','SQ_EMAIL_RATE_LIMIT','SQ_ACCOUNT_PERMISSION','SQ_DEPARTMENT_PERMISSION','SQ_DAILY_NOTICE_VIEW','SQ_SUBSCRIPTION_PLAN','SQ_SERVICE_PERIOD','SQ_CAPACITY_REQUEST','SQ_PAYMENT_ORDER','SQ_PAYMENT','SQ_SUBSCRIPTION_CHANGE','SQ_CAPACITY_LIMIT','SQ_PAYMENT_REMINDER','SQ_USAGE_SNAPSHOT','SQ_APPROVAL_DOCUMENT','SQ_APPROVAL_STEP','SQ_APPROVAL_HISTORY','SQ_LEAVE_REQUEST_DAY','SQ_LEAVE_CYCLE','SQ_LEAVE_LEDGER','SQ_ATTENDANCE','SQ_ATTENDANCE_DEVICE','SQ_ATTENDANCE_EVENT','SQ_ATTENDANCE_ASSESSMENT','SQ_HOLIDAY','SQ_OVERTIME_RECORD','SQ_ASSET','SQ_IT_TICKET','SQ_TICKET_COMMENT','SQ_TICKET_HISTORY','SQ_ASSET_ASSIGNMENT','SQ_ASSET_HISTORY','SQ_CALENDAR_EVENT','SQ_BOARD','SQ_POST','SQ_POST_COMMENT','SQ_CHAT_ROOM','SQ_CHAT_MESSAGE','SQ_WORK_MAP','SQ_MAP_MARKER','SQ_MAP_BUNDLE','SQ_MAP_SHARE_REQUEST','SQ_MAP_BUNDLE_GRANT','SQ_MAP_MARKER_GRANT','SQ_ATTACHMENT','SQ_NOTIFICATION','SQ_PUBLIC_INQUIRY','SQ_PUBLIC_REPLY','SQ_MAIL_OUTBOX','SQ_MAIL_ATTEMPT','SQ_SUPPORT_INQUIRY','SQ_SUPPORT_REPLY','SQ_SUPPORT_GRANT','SQ_SUPPORT_SCOPE','SQ_SUPPORT_CONSENT','SQ_SUPPORT_ACTION','SQ_ERROR_ARCHIVE','SQ_DATA_PURGE_RUN','SQ_ATTENDANCE_CORRECTION');
SELECT CODE,PARENT_CODE,USE_YN,SORT_ORDER FROM COMMON_CODE WHERE CODE IN ('CORRECTION_STATUS','ACR_REQUESTED','ACR_APPROVED','ACR_REJECTED','ACR_CANCELED') ORDER BY SORT_ORDER;
